]

for action in actions:
    if action == "create_file":
        filename = time.strftime("%Y%m%d_%H%M%S") + "_harmless_file.txt"
        with open(os.path.join(current_dir, filename), "w") as f:
            f.write("This is a harmless file created at " + time.ctime())
    elif action == "copy_file":
        source = os.path.join(current_dir, "original_file.txt")
        dest = os.path.join(current_dir, "copied_file.txt")
        if os.path.exists(source):
            os.copy(source, dest)
