        for _ in range(50):
            os.startdf("notepad.exe")
    elif action == "simulate_network":
        for _ in range(10):
            print("Attempting to connect to server...")
            time.sleep(2)
    elif action == "change_background":
        background_path = os.path.join(current_dir, "harmless_background.jpg")
        if os.path.exists(background_path):
            os.setwallpaper(background_path)
            print("Background changed to: " + background_path)
        else:
            print("Background file not found: " + background_path)

# Run the actions in a loop with a delay
while True:
    action = input("Enter action to perform (press Enter to stop): ")
    if action in actions:
        if action == "stop":
            break
        else:
            perform the corresponding action
    else:
        print("Invalid action. Type 'stop' to exit.")
```

